package in.kalaimarket;
import java.time.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.web.server.ResponseStatusException;
import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class OrderServiceTest {
 final AutoSignalRepository signals=mock(AutoSignalRepository.class);final TradeRepository plans=mock(TradeRepository.class);final FeedLockRepository locks=mock(FeedLockRepository.class);final MarketQuoteRepository quotes=mock(MarketQuoteRepository.class);final BrokerExecutionRepository executions=mock(BrokerExecutionRepository.class);
 final OrderService service=new OrderService(signals,plans,locks,quotes,executions);
 ManualOrderRequest request(AutoSignal.PendingKind kind,BigDecimal entry,List<BigDecimal> targets){return new ManualOrderRequest(UUID.randomUUID(),null,"XAUUSD",TradePlan.Direction.BUY,Timeframe.M1,kind,entry,new BigDecimal("90"),targets,Instant.now().plusSeconds(3600));}
 @BeforeEach void setup(){when(locks.lock("XAUUSD")).thenReturn(Optional.of(new WatchItem()));var q=new MarketQuote();q.symbol="XAUUSD";q.bid=new BigDecimal("99");q.ask=new BigDecimal("99.2");q.quotedAt=Instant.now();when(quotes.findById("XAUUSD")).thenReturn(Optional.of(q));when(signals.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));}
 @Test void manualStopQueuesExactTargetsAndExpiry(){var r=request(AutoSignal.PendingKind.STOP,new BigDecimal("100"),List.of(new BigDecimal("110"),new BigDecimal("120"),new BigDecimal("130")));var s=service.manual(r);assertEquals("MANUAL_PENDING_V1",s.strategy);assertEquals(r.targets(),s.targets);assertEquals(r.expiresAt(),s.expiresAt);assertEquals(AutoSignal.Status.PENDING,s.status);}
 @Test void limitAllowsPullbackEntryAndSingleFinalTarget(){var s=service.manual(request(AutoSignal.PendingKind.LIMIT,new BigDecimal("95"),List.of(new BigDecimal("110"))));assertEquals(s.tp1,s.tp2);assertEquals(AutoSignal.PendingKind.LIMIT,s.pendingKind);}
 @Test void invalidLevelsAndWrongPendingSideCannotQueue(){assertThrows(ResponseStatusException.class,()->service.manual(request(AutoSignal.PendingKind.STOP,new BigDecimal("95"),List.of(new BigDecimal("110")))));assertThrows(ResponseStatusException.class,()->service.manual(request(AutoSignal.PendingKind.STOP,new BigDecimal("100"),List.of(new BigDecimal("120"),new BigDecimal("110")))));verify(signals,never()).saveAndFlush(any());}
 @Test void repeatRequestReturnsSameSignalWithoutAnotherInsert(){var r=request(AutoSignal.PendingKind.STOP,new BigDecimal("100"),List.of(new BigDecimal("110")));var s=new AutoSignal();s.id=7L;when(signals.findByRequestKey(r.requestKey())).thenReturn(Optional.of(s));assertSame(s,service.manual(r));verify(signals,never()).saveAndFlush(any());}
 @Test void staleQuoteAndDisabledFrameCannotQueue(){var q=quotes.findById("XAUUSD").orElseThrow();q.quotedAt=Instant.now().minusSeconds(120);assertThrows(ResponseStatusException.class,()->service.manual(request(AutoSignal.PendingKind.STOP,new BigDecimal("100"),List.of(new BigDecimal("110")))));}
 @Test void pendingCancelDoesNotCloseOpenPosition(){var s=new AutoSignal();s.id=7L;when(signals.findById(7L)).thenReturn(Optional.of(s));service.cancel(7);assertTrue(s.cancelRequested);assertEquals(AutoSignal.Status.CANCELLED,s.status);var e=new BrokerExecution();e.status=BrokerExecution.Status.OPEN;when(executions.findBySignalId(7L)).thenReturn(Optional.of(e));assertThrows(ResponseStatusException.class,()->service.cancel(7));}
}
